output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves border both sides of a one-cell-wide passage.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "Agents must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartMoveIntoSingleFile": {
          "pre": {
            "and": [
              "hasCart",
              "moveAction"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartMoveIntoSingleFile"
    }
  },
  {
    "id": "drop_cart_only_at_aisle_mouth",
    "text": "If an agent puts down a cart, it must be at a designated wide aisle mouth before a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "designatedCartParking": {
          "and": [
            "wideCrossAisle",
            "upperAisleMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartParking"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at a narrow-aisle mouth, the agent is obliged to retrieve a cart before the trip ends.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideCartParkingMouth": {
          "and": [
            "upperAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "wideCartParkingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "wideCartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "return_to_cart_after_narrow_shelf",
    "text": "After interacting with a shelf while on foot in a single-file aisle, the agent must return to a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "narrowShelfUseOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "narrowShelfUseOnFoot",
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_acquire_only_at_bay_or_parking",
    "text": "An agent may acquire a cart only at the entrance cart bay or at a designated temporary parking mouth.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideParkingMouth": {
          "and": [
            "upperAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        },
        "allowedCartAcquirePlace": {
          "or": [
            "cartBay",
            "wideParkingMouth"
          ]
        }
      },
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "acquireCart",
          {
            "not": "allowedCartAcquirePlace"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_roaming_open_store",
    "text": "Except at the entrance/cart bay and during a narrow-aisle cart-free excursion, agents must not move around the open store without a cart.",
    "abstraction": {
      "state_properties": {
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        },
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "parkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceOrCartBay",
            "singleFileShelfAisle",
            "parkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "moveAction",
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west",
    "text": "The store circulation norm forbids moving westward.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "westwardMove": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westwardMove"
    }
  }
]
